private static bool IsPublicReadable(ISymbol member) => member switch
{
    IPropertySymbol property => property.DeclaredAccessibility == Accessibility.Public
        && property.GetMethod is { DeclaredAccessibility: Accessibility.Public },
    IFieldSymbol field => field.DeclaredAccessibility == Accessibility.Public && !field.IsConst,
    _ => false,
};

private static bool IsPublicWritable(ISymbol member) => member switch
{
    IPropertySymbol property => property.DeclaredAccessibility == Accessibility.Public
        && property.SetMethod is { DeclaredAccessibility: Accessibility.Public },
    IFieldSymbol field => field.DeclaredAccessibility == Accessibility.Public && !field.IsReadOnly && !field.IsConst,
    _ => false,
};

/// <summary>
/// Finds the accessible constructor with the most parameters whose names (case-insensitive) and types all match serialized members.
/// </summary>
/// <returns>The members passed to the constructor, in parameter order; or <see langword="null"/> if no constructor matches.</returns>
private static MemberSerializationInfo[]? MatchConstructorParameters(Compilation compilation, INamedTypeSymbol type, INamedTypeSymbol formatter, IReadOnlyList<MemberSerializationInfo> members)
{
    foreach (IMethodSymbol ctor in type.InstanceConstructors
        .Where(c => compilation.IsSymbolAccessibleWithin(c, formatter))
        .OrderByDescending(c => c.Parameters.Length))
    {
        MemberSerializationInfo[] parameters = new MemberSerializationInfo[ctor.Parameters.Length];
        bool matched = true;
        for (int i = 0; i < parameters.Length && matched; i++)
        {
            IParameterSymbol parameter = ctor.Parameters[i];
            MemberSerializationInfo[] candidates = members.Where(m => string.Equals(m.Name, parameter.Name, StringComparison.OrdinalIgnoreCase)).ToArray();
            if (candidates.Length == 1 && candidates[0].Type == parameter.Type.ToDisplayString(SymbolDisplayFormat.FullyQualifiedFormat))
            {
                parameters[i] = candidates[0];
            }
            else
            {
                matched = false;
            }
        }

        if (matched)
        {
            return parameters;
        }
    }

    return null;
}

